import { closeDb, initDb } from "../lib/db";
import { mongoCollection, withMongoTransaction } from "../lib/mongo";

export async function cleanupMarketplaceQa() {
  await initDb();
  // Only the exact timestamp-based addresses generated by the local browser test qualify.
  // Never delete accounts or match a real mailbox/domain or arbitrary QA suffix.
  const adminEmail = /^qa-marketplace-admin-\d{13}@example\.test$/;
  const providerEmail = /^qa-marketplace-provider-\d{13}@example\.test$/;
  const result = await withMongoTransaction(async session => {
    const users = await mongoCollection("users");
    const admins = await users.find({ email: adminEmail }, { projection: { id: 1 }, session }).toArray();
    const providers = await users.find({ email: providerEmail }, { projection: { id: 1 }, session }).toArray();
    const adminIds = admins.map(user => user.id), providerIds = providers.map(user => user.id);
    const revoked = await users.updateMany({ id: { $in: adminIds }, email: adminEmail, role: "admin" }, { $set: { role: "customer" } }, { session });
    await (await mongoCollection("sessions")).deleteMany({ user_id: { $in: adminIds } }, { session });
    const withdrawn = await (await mongoCollection("marketplace_providers")).updateMany({ user_id: { $in: providerIds } }, { $set: { active: 0, verified: 0 }, $inc: { reservation_version: 1 } }, { session });
    return { revoked: revoked.modifiedCount, withdrawn: withdrawn.modifiedCount };
  });
  return result;
}
if (process.argv[1] && /[\\/]cleanup-marketplace-qa\.(?:ts|js)$/.test(process.argv[1])) {
  cleanupMarketplaceQa().then(result => console.log(`Temporary QA administrator roles revoked: ${result.revoked}; QA provider profiles withdrawn: ${result.withdrawn}.`))
    .catch(error => { console.error(error instanceof Error ? error.message : "QA cleanup failed"); process.exitCode = 1; }).finally(closeDb);
}
